const $=(s,r=document)=>r.querySelector(s);
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const sb=(window.CFG.URL&&window.supabase)?window.supabase.createClient(CFG.URL,CFG.KEY):null;
const pub=(b,p)=>sb.storage.from(b).getPublicUrl(p).data.publicUrl;
const LOGO="data:image/png;base64,";
const page=document.body.dataset.page;
const L=[["index.html","Home","home"],["papers.html","Research Papers","papers"],["gallery.html","Gallery","gallery"]];
$("#hdr").innerHTML=`<div class="bar"><a class="logo" href="index.html" aria-label="Nova M&A Club – Home"><img src="${LOGO}" alt="Nova SBE Mergers and Acquisitions Student Club"></a><button class="burger" aria-label="Menu" aria-expanded="false">☰</button><nav>${L.map(l=>`<a href="${l[0]}"${l[2]===page?' aria-current="page"':""}>${l[1]}</a>`).join("")}</nav></div>`;
$(".burger").onclick=e=>{const o=$("nav").classList.toggle("open");e.currentTarget.setAttribute("aria-expanded",o)};
$("#ftr").innerHTML=`<div class="wrap"><strong>Nova M&amp;A Club</strong> · Nova SBE Mergers and Acquisitions Student Club<p><a href="mailto:ma.club@novasbe.pt">ma.club@novasbe.pt</a> · <a href="https://instagram.com/novamaclub" rel="noopener">@novamaclub</a> · LinkedIn: Nova M&amp;A Club</p><a href="admin.html" class="note" style="color:#9fb0d6">Admin</a></div>`;

const fi=document.querySelector('link[rel=icon]');if(fi)fi.href=LOGO;
